// Local, opt-in QA only (?qa=1). No requests or visitor telemetry.
const output=document.createElement('output');output.id='qa-metrics';output.hidden=true;document.body.append(output);
const result={lcpMs:null,cls:0,longTasks:0,longestTaskMs:0,garageFirstFrameMs:null,frameSample:null};
function publish(){const nav=performance.getEntriesByType('navigation')[0];const garage=performance.getEntriesByName('garage-first-frame-time')[0];result.phases=Object.fromEntries(performance.getEntriesByType('measure').filter(m=>m.name.startsWith('garage-phase-')).map(m=>[m.name.replace('garage-phase-',''),Math.round(m.duration)]));result.garageFirstFrameMs=garage?Math.round(garage.duration):null;result.domContentLoadedMs=nav?Math.round(nav.domContentLoadedEventEnd):null;const resources=performance.getEntriesByType('resource');result.resourceBytes=resources.reduce((n,r)=>n+r.encodedBodySize,0);result.resourceCount=resources.length;output.textContent=JSON.stringify(result);}
for(const type of ['largest-contentful-paint','layout-shift','longtask'])try{new PerformanceObserver(list=>{for(const e of list.getEntries()){if(type==='largest-contentful-paint')result.lcpMs=Math.round(e.startTime);if(type==='layout-shift'&&!e.hadRecentInput)result.cls+=e.value;if(type==='longtask'){result.longTasks++;result.longestTaskMs=Math.max(result.longestTaskMs,Math.round(e.duration));}}publish();}).observe({type,buffered:true});}catch{}
let sampling=false;
function sampleFrames(){if(sampling)return;sampling=true;const deltas=[];let first=0,last=0;function tick(now){if(!first)first=now;if(last)deltas.push(now-last);last=now;if(now-first<4000){requestAnimationFrame(tick);return;}const sorted=[...deltas].sort((a,b)=>a-b);result.frameSample={frames:deltas.length,over20ms:deltas.filter(n=>n>20).length,over50ms:deltas.filter(n=>n>50).length,p95Ms:Math.round(sorted[Math.floor(sorted.length*.95)]||0),maxMs:Math.round(Math.max(...deltas))};sampling=false;publish();}requestAnimationFrame(tick);}
document.querySelector('#viewer')?.addEventListener('pointerdown',sampleFrames,{passive:true});
document.querySelector('#rotate')?.addEventListener('click',sampleFrames,{passive:true});
setInterval(publish,1000);publish();
